#include <iostream>
#include <cmath>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long x1, y1, x2, y2;
    long long x, y;

    cin >> x1 >> y1 >> x2 >> y2;
    cin >> x >> y;

    long long dx = x2 - x1;
    long long dy = y2 - y1;

    bool reachable = true;

    // Check x-coordinate
    if (x == 0) {
        if (dx != 0) reachable = false;
    } else {
        if (dx % x != 0) reachable = false;
    }

    // Check y-coordinate
    if (y == 0) {
        if (dy != 0) reachable = false;
    } else {
        if (dy % y != 0) reachable = false;
    }

    if (!reachable) {
        cout << "NO" << endl;
        return 0;
    }

    // Calculate number of moves needed in each dimension
    // Moves count can be negative, we care about parity
    long long kx = (x == 0) ? 0 : (dx / x);
    long long ky = (y == 0) ? 0 : (dy / y);

    // Parity check: total number of moves k must satisfy kx ≡ k (mod 2) and ky ≡ k (mod 2)
    // This implies kx and ky must have the same parity.
    // In C++, % on negative numbers yields negative remainder.
    // (val % 2 + 2) % 2 ensures a positive modulo 2 result (0 or 1).
    int parity_x = (kx % 2 + 2) % 2;
    int parity_y = (ky % 2 + 2) % 2;

    if (parity_x == parity_y) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}
